import React, { useEffect, useState } from 'react';
import { getAllOrders, getProducts, computeStats } from './api';

const STATUS_COLOR = {
  pending:   'yellow',
  confirmed: 'blue',
  shipped:   'blue',
  delivered: 'green',
  cancelled: 'red',
};

export default function AdminDashboard() {
  const [stats,   setStats]   = useState(null);
  const [recent,  setRecent]  = useState([]);
  const [loading, setLoading] = useState(true);
  const [error,   setError]   = useState(null);

  useEffect(() => {
    async function load() {
      try {
        setError(null);
        const [oRes, pRes] = await Promise.all([
          getAllOrders(), 
          getProducts({ limit: 999 })
        ]);

        const orders   = oRes?.orders   || [];
        const products = pRes?.products || [];

        const computedStats = computeStats(orders, products);
        setStats(computedStats);
        setRecent(orders.slice(0, 8));

      } catch (err) {
        console.error("Dashboard load error:", err);
        setError(err.message || "Failed to load dashboard data");

        // Fallback mock data so UI doesn't crash
        setStats({
          revenue: 0,
          orders: 0,
          products: 0,
          pending: 0,
        });
        setRecent([]);
      } finally {
        setLoading(false);
      }
    }
    load();
  }, []);

  if (loading) return <PageLoad />;

  if (error) {
    return (
      <div style={{ padding: '40px', textAlign: 'center', color: '#e05252' }}>
        <h2>Error Loading Dashboard</h2>
        <p>{error}</p>
        <button 
          onClick={() => window.location.reload()}
          style={{ marginTop: 16, padding: '10px 20px' }}
        >
          Retry
        </button>
      </div>
    );
  }

  // Safe fallback in case stats is still null
  const safeStats = stats || { revenue: 0, orders: 0, products: 0, pending: 0 };

  const cards = [
    { 
      label: 'Total Revenue',  
      value: `$${Number(safeStats.revenue).toLocaleString('en', { minimumFractionDigits: 2 })}`, 
      icon: <RevenueIcon />, 
      color: '#c9a96e' 
    },
    { 
      label: 'Total Orders',   
      value: safeStats.orders,   
      icon: <OrderIcon />,   
      color: '#5b8df5' 
    },
    { 
      label: 'Products',       
      value: safeStats.products, 
      icon: <BoxIcon />,     
      color: '#52c07a' 
    },
    { 
      label: 'Pending Orders', 
      value: safeStats.pending,  
      icon: <ClockIcon />,   
      color: '#e05252' 
    },
  ];

  return (
    <div style={styles.page}>
      <div style={styles.header}>
        <div>
          <h1 style={styles.h1}>Dashboard</h1>
          <p style={{ color: 'var(--muted)', fontSize: 13 }}>
            {new Date().toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' })}
          </p>
        </div>
      </div>

      {/* Stat Cards */}
      <div style={styles.statsGrid}>
        {cards.map((c, i) => (
          <div key={i} className="card" style={{ ...styles.statCard, '--c': c.color }}>
            <div style={{ ...styles.statIcon, background: c.color + '18', color: c.color }}>
              {c.icon}
            </div>
            <div style={styles.statValue}>{c.value}</div>
            <div style={styles.statLabel}>{c.label}</div>
            <div style={{ ...styles.statAccent, background: c.color }} />
          </div>
        ))}
      </div>

      {/* Recent Orders */}
      <div className="card" style={{ marginTop: 24 }}>
        <div style={styles.sectionHead}>
          <h2 style={styles.h2}>Recent Orders</h2>
          <span style={{ fontSize: 12, color: 'var(--muted)' }}>{recent.length} latest</span>
        </div>
        <div className="table-wrap" style={{ marginTop: 16 }}>
          <table>
            <thead>
              <tr>
                <th>Order #</th>
                <th>Customer</th>
                <th>Email</th>
                <th>Amount</th>
                <th>Payment</th>
                <th>Status</th>
                <th>Date</th>
              </tr>
            </thead>
            <tbody>
              {recent.map(o => (
                <tr key={o.id}>
                  <td style={{ fontWeight: 600, color: 'var(--accent)' }}>#{o.id}</td>
                  <td>{o.user_name || '—'}</td>
                  <td style={{ color: 'var(--muted)' }}>{o.email || '—'}</td>
                  <td>${Number(o.total_amount || 0).toFixed(2)}</td>
                  <td style={{ textTransform: 'uppercase', fontSize: 11, letterSpacing: '0.05em' }}>
                    {o.payment_method || '—'}
                  </td>
                  <td>
                    <span className={`badge badge-${STATUS_COLOR[o.status] || 'gray'}`}>
                      {o.status || 'unknown'}
                    </span>
                  </td>
                  <td style={{ color: 'var(--muted)', fontSize: 12 }}>
                    {o.created_at ? new Date(o.created_at).toLocaleDateString() : '—'}
                  </td>
                </tr>
              ))}
              {!recent.length && (
                <tr>
                  <td colSpan={7} style={{ textAlign:'center', color:'var(--muted)', padding:'40px 0' }}>
                    No orders yet
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

// Keep your existing PageLoad and styles...
function PageLoad() {
  return (
    <div style={{ display:'flex', alignItems:'center', justifyContent:'center', height:'60vh' }}>
      <span className="spinner" style={{ width:32, height:32 }} />
    </div>
  );
}

const styles = { /* ... your existing styles ... */ };

// Keep your icon components...
function RevenueIcon() { /* ... */ }
function OrderIcon() { /* ... */ }
function BoxIcon() { /* ... */ }
function ClockIcon() { /* ... */ }
